using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Operations;
using RoslynSentinel.Common.AgentLoop;

namespace RoslynSentinel.Tests.ModelEval.ImplementationScenarios.ErrorRecovery;

/// <summary>
/// Sweep 14 `new Dictionary&lt;FilePath, string&gt;` sites in four files to `new DocumentChangeSet`, leave the FailedFiles
/// decoy, and leave the three sites that stop compiling once converted (CS0266). The four target files are generated by one
/// template per file: the seed spells the creation type as Dictionary, the golden as DocumentChangeSet.
/// </summary>
internal static class SweepConstructionSitesScenario
{
    private const string CoreFolder = "ContosoOrders.Core/Evals/SweepConstructionSites/";
    private const string TestFolder = "ContosoOrders.Tests/Evals/SweepConstructionSites/";
    private const string DictionaryType = "Dictionary<FilePath, string>";
    private const string SetType = "DocumentChangeSet";

    private static readonly string[] TargetPaths =
    {
        CoreFolder + "Planner.cs",
        CoreFolder + "Renamer.cs",
        CoreFolder + "Mover.cs",
        CoreFolder + "Merger.cs",
    };

    private const string FilePathSource = """
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>A file path compared case-insensitively.</summary>
public readonly record struct FilePath(string Value)
{
    public bool Equals(FilePath other) => string.Equals(Value, other.Value, StringComparison.OrdinalIgnoreCase);

    public override int GetHashCode() => StringComparer.OrdinalIgnoreCase.GetHashCode(Value ?? string.Empty);

    public override string ToString() => Value;

    public static implicit operator FilePath(string value) => new(value);
}
""";

    private const string DocumentChangeSetSource = """
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>A change set: file path to new file content.</summary>
public sealed class DocumentChangeSet : Dictionary<FilePath, string>
{
    public DocumentChangeSet()
    {
    }

    public DocumentChangeSet(int capacity)
        : base(capacity)
    {
    }

    public DocumentChangeSet(IDictionary<FilePath, string> source)
        : base(source)
    {
    }
}
""";

    private const string PlanResultSource = """
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>New content per path, and a failure reason per path that could not be planned.</summary>
public sealed record PlanResult(Dictionary<FilePath, string> Changes, Dictionary<FilePath, string> FailedFiles);
""";

    private const string TestsSource = """
using ContosoOrders.Evals.SweepConstructionSites;
using Xunit;

namespace ContosoOrders.Tests.Evals.SweepConstructionSites;

public class SweepTests
{
    [Fact]
    public void PlanAddBuildsOneEntryPerPath()
    {
        var result = Planner.PlanAdd(new[] { "a.cs", "b.cs" });
        Assert.Equal(2, result.Changes.Count);
        Assert.Empty(result.FailedFiles);
    }

    [Fact]
    public void MergeKeepsTheLaterEntry()
    {
        var first = new Dictionary<FilePath, string> { ["a.cs"] = "1" };
        var second = new Dictionary<FilePath, string> { ["a.cs"] = "2" };
        Assert.Equal("2", Merger.Merge(first, second)["a.cs"]);
    }

    [Fact]
    public void OverlayAddsOneEntry()
    {
        var overlaid = Mover.Overlay(new Dictionary<FilePath, string> { ["a.cs"] = "1" });
        Assert.Equal(2, overlaid.Count);
    }
}
""";

    // Visible acceptance tests (Spec S6). Red on the seed: ReturnedMapIsADocumentChangeSet (all 13 producers). Green on the golden: all seven.
    // PlanAdd_FailedFilesStaysAPlainDictionary is green on both. The FromResult/Choose/Latest tests use plain dictionaries, so a cast
    // conversion throws InvalidCastException there.
    private const string AcceptanceTestsSource = """
using ContosoOrders.Evals.SweepConstructionSites;
using Xunit;

namespace ContosoOrders.Tests.Evals.SweepConstructionSites;

public class ConstructionSiteTests
{
    public static TheoryData<string> Producers => new()
    {
        "PlanAdd",
        "PlanTwo",
        "PlanCopy",
        "RenameAll",
        "Preview",
        "None",
        "Move",
        "MoveWith",
        "Stage",
        "Overlay",
        "Merge",
        "MergeAll",
        "Combine",
    };

    private static Dictionary<FilePath, string> Plain(string path, string content) => new() { [path] = content };

    private static PlanResult Plan(Dictionary<FilePath, string> changes, Dictionary<FilePath, string>? failedFiles = null) =>
        new(changes, failedFiles ?? new Dictionary<FilePath, string>());

    private static Dictionary<FilePath, string> Produce(string producer) => producer switch
    {
        "PlanAdd" => Planner.PlanAdd(new[] { "a.cs" }).Changes,
        "PlanTwo" => Planner.PlanTwo(),
        "PlanCopy" => Planner.PlanCopy(Plain("a.cs", "1")),
        "RenameAll" => Renamer.RenameAll(new[] { "a.cs" }),
        "Preview" => Renamer.Preview(new List<string> { "a.cs" }),
        "None" => Renamer.None(),
        "Move" => Mover.Move(new[] { "a.cs" }),
        "MoveWith" => Mover.MoveWith(),
        "Stage" => Mover.Stage(),
        "Overlay" => Mover.Overlay(Plain("a.cs", "1")),
        "Merge" => Merger.Merge(Plain("a.cs", "1"), Plain("b.cs", "2")),
        "MergeAll" => Merger.MergeAll(new[] { Plain("a.cs", "1"), Plain("b.cs", "2") }),
        "Combine" => Merger.Combine(),
        _ => throw new ArgumentException($"Unknown producer {producer}.", nameof(producer)),
    };

    [Theory]
    [MemberData(nameof(Producers))]
    public void ReturnedMapIsADocumentChangeSet(string producer)
    {
        var map = Produce(producer);
        Assert.True(
            map.GetType() == typeof(DocumentChangeSet),
            $"{producer} returned a {map.GetType().Name}, not a DocumentChangeSet.");
    }

    [Fact]
    public void PlanAdd_FailedFilesStaysAPlainDictionary()
    {
        var failedFiles = Planner.PlanAdd(new[] { "a.cs" }).FailedFiles;
        Assert.True(
            failedFiles.GetType() == typeof(Dictionary<FilePath, string>),
            $"FailedFiles is a {failedFiles.GetType().Name}; it maps a path to a reason and must stay a plain Dictionary.");
    }

    [Fact]
    public void FromResult_WithAPlainDictionary_ReturnsItsEntriesAndDoesNotThrow()
    {
        var map = Renamer.FromResult(Plan(Plain("a.cs", "1")));
        Assert.Single(map);
        Assert.Equal("1", map["a.cs"]);
    }

    [Fact]
    public void FromResult_WithFailedFiles_ReturnsAnEmptyMap()
    {
        var map = Renamer.FromResult(Plan(Plain("a.cs", "1"), Plain("b.cs", "cannot plan")));
        Assert.Empty(map);
    }

    [Fact]
    public void Choose_WithAPlainDictionary_ReturnsItsEntriesAndDoesNotThrow()
    {
        var map = Mover.Choose(Plan(Plain("a.cs", "1")));
        Assert.Single(map);
        Assert.Equal("1", map["a.cs"]);
    }

    [Fact]
    public void Choose_WithNoChanges_ReturnsAnEmptyMap()
    {
        var map = Mover.Choose(Plan(new Dictionary<FilePath, string>()));
        Assert.Empty(map);
    }

    [Fact]
    public void Latest_PrefersTheSecondWhenItHasEntries_AndNeverThrows()
    {
        var first = Plan(Plain("a.cs", "1"));
        var second = Plan(Plain("b.cs", "2"));

        var preferred = Merger.Latest(first, second);
        Assert.Single(preferred);
        Assert.Equal("2", preferred["b.cs"]);

        var fallback = Merger.Latest(first, Plan(new Dictionary<FilePath, string>()));
        Assert.Single(fallback);
        Assert.Equal("1", fallback["a.cs"]);
    }
}
""";

    private static string PlannerSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Plans changes.</summary>
public static class Planner
{
    public static PlanResult PlanAdd(IEnumerable<string> paths)
    {
        var changes = new {{set}}();
        foreach (var path in paths)
        {
            changes[path] = "// added";
        }

        return new PlanResult(changes, FailedFiles: new Dictionary<FilePath, string>());
    }

    public static Dictionary<FilePath, string> PlanTwo()
    {
        return new {{set}} { ["a.cs"] = "one", ["b.cs"] = "two" };
    }

    public static Dictionary<FilePath, string> PlanCopy(Dictionary<FilePath, string> source)
    {
        return new {{set}}(source);
    }
}
""";

    private static string RenamerSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Plans renames.</summary>
public static class Renamer
{
    public static Dictionary<FilePath, string> RenameAll(IEnumerable<string> paths)
    {
        var renamed = new {{set}}();
        foreach (var path in paths)
        {
            renamed[path + ".bak"] = path;
        }

        return renamed;
    }

    public static Dictionary<FilePath, string> Preview(List<string> paths)
    {
        var map = new {{set}}(paths.Count);
        foreach (var path in paths)
        {
            map[path] = "preview";
        }

        return map;
    }

    public static Dictionary<FilePath, string> None() => new {{set}}();

    public static Dictionary<FilePath, string> FromResult(PlanResult plan)
    {
        var changes = new Dictionary<FilePath, string>();
        if (plan.FailedFiles.Count == 0)
        {
            changes = plan.Changes;
        }

        return changes;
    }
}
""";

    private static string MoverSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Plans moves.</summary>
public static class Mover
{
    public static Dictionary<FilePath, string> Move(IEnumerable<string> paths)
    {
        var moved = new {{set}}();
        foreach (var path in paths)
        {
            moved[path] = "// moved";
        }

        return moved;
    }

    public static Dictionary<FilePath, string> MoveWith()
    {
        var pending = new {{set}} { ["x.cs"] = "x" };
        pending["y.cs"] = "y";
        return pending;
    }

    public static Dictionary<FilePath, string> Stage()
    {
        Dictionary<FilePath, string> staged = new {{set}}();
        staged["s.cs"] = "s";
        return staged;
    }

    public static Dictionary<FilePath, string> Overlay(Dictionary<FilePath, string> first)
    {
        return new {{set}}(first) { ["z.cs"] = "z" };
    }

    public static Dictionary<FilePath, string> Choose(PlanResult plan)
    {
        var chosen = new Dictionary<FilePath, string>();
        if (plan.Changes.Count > 0)
        {
            chosen = plan.Changes;
        }

        return chosen;
    }
}
""";

    private static string MergerSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Merges change sets.</summary>
public static class Merger
{
    public static Dictionary<FilePath, string> Merge(Dictionary<FilePath, string> a, Dictionary<FilePath, string> b)
    {
        var merged = new {{set}}(a);
        foreach (var (path, content) in b)
        {
            merged[path] = content;
        }

        return merged;
    }

    public static Dictionary<FilePath, string> MergeAll(IEnumerable<Dictionary<FilePath, string>> sets)
    {
        var all = new {{set}}();
        foreach (var current in sets)
        {
            foreach (var (path, content) in current)
            {
                all[path] = content;
            }
        }

        return all;
    }

    public static Dictionary<FilePath, string> Combine()
    {
        return Merge(new {{set}}(), new {{set}} { ["m.cs"] = "m" });
    }

    public static Dictionary<FilePath, string> Latest(PlanResult first, PlanResult second)
    {
        var latest = new Dictionary<FilePath, string>();
        latest = second.Changes.Count > 0 ? second.Changes : first.Changes;
        return latest;
    }
}
""";

    private const string CannedReport = """
DONE: converted 14 sites to new DocumentChangeSet, keeping arguments and initializers; left the FailedFiles map in Planner.PlanAdd as a plain Dictionary and three sites unconverted (below).
FromResult: CS0266 once converted, because plan.Changes (a plain Dictionary) is assigned to the same variable afterwards.
Choose: CS0266 once converted, because plan.Changes (a plain Dictionary) is assigned to the same variable afterwards.
Latest: CS0266 once converted, because a plain Dictionary from the plan results is assigned to the same variable afterwards.
""";

    // Expression-bodied on purpose: a static readonly field would render before the contract placement is known (initialisation order).
    private static string StepPrompt => EvalContractOptions.Render(new ScenarioTask(
        Goal: "In ContosoOrders.Core/Evals/SweepConstructionSites, Planner, Renamer, Mover and Merger build their change-set maps as plain `Dictionary<FilePath, string>`. " +
            "We are about to add behaviour to `DocumentChangeSet` (DocumentChangeSet.cs, a subclass of `Dictionary<FilePath, string>`), " +
            "so every map these four files build and return must be a `DocumentChangeSet`. Create them as `new DocumentChangeSet`, " +
            "keeping constructor arguments and initializers. Public method signatures stay as they are.",
        Files: "Planner.cs, Renamer.cs, Mover.cs and Merger.cs in ContosoOrders.Core/Evals/SweepConstructionSites. No other file.",
        Conditions: "The map passed as `FailedFiles` maps a path to a failure reason, not to content: it stays a plain Dictionary. " +
            "No method may start throwing; behaviour is otherwise unchanged.",
        IfFails: "If a site cannot be converted without breaking the build or a method's behaviour, leave that site as it is, " +
            "convert the rest, and end with DONE: naming the site and the reason.",
        DoneWhen: "The solution builds with 0 errors; all tests in ContosoOrders.Tests pass, including the new class ConstructionSiteTests " +
            "(ContosoOrders.Tests/Evals/SweepConstructionSites/ConstructionSiteTests.cs) and SweepTests; no file outside Files changed.",
        Report: "Every site you left unconverted: the method name and the compiler error or the reason. Write `none` if there is none."));

    // The contract placement is read once per process, when this Definition initialises (StepPrompt renders then); one process runs one arm.
    public static ImplementationScenario Definition { get; } = new ImplementationScenario(
        "SweepConstructionSites",
        "Sweep construction sites to DocumentChangeSet, skipping the ones that would not compile",
        "tool use, recovery",
        "DCS briefs/orchestrator-agent-a6275963dc0ea11af briefs 01/10, commits 269ec636, d4501b98",
        new Dictionary<string, string>
        {
            [CoreFolder + "FilePath.cs"] = FilePathSource,
            [CoreFolder + "DocumentChangeSet.cs"] = DocumentChangeSetSource,
            [CoreFolder + "PlanResult.cs"] = PlanResultSource,
            [TargetPaths[0]] = PlannerSource(DictionaryType),
            [TargetPaths[1]] = RenamerSource(DictionaryType),
            [TargetPaths[2]] = MoverSource(DictionaryType),
            [TargetPaths[3]] = MergerSource(DictionaryType),
            [TestFolder + "SweepTests.cs"] = TestsSource,
            [TestFolder + "ConstructionSiteTests.cs"] = AcceptanceTestsSource,
        },
        new[]
        {
            new ImplementationScenarioStep(
                Prompt: StepPrompt,
                GoldenFiles: new Dictionary<string, string>
                {
                    [TargetPaths[0]] = PlannerSource(SetType),
                    [TargetPaths[1]] = RenamerSource(SetType),
                    [TargetPaths[2]] = MoverSource(SetType),
                    [TargetPaths[3]] = MergerSource(SetType),
                },
                AllowedPaths: TargetPaths.ToList(),
                HiddenTestSource: null,
                ExtraCheck: static ctx => Task.FromResult<string?>(CheckSweep(ctx)),
                CannedFinalMessage: CannedReport,
                DoneWhenTests: new[] { "ConstructionSiteTests", "SweepTests" }),
        },
        PreferredHost: "113",
        PrimaryAxis: EvalAxis.ErrorRecovery);

    /// <summary>
    /// Every creation in the four target files whose compiled type is exactly Dictionary&lt;FilePath, string&gt; (not the FailedFiles
    /// argument) is a site the model left unconverted; the final message must name each such site's method, as a Report line label
    /// or value or on the DONE: line. `none` passes only when no site remains. Scope and behaviour are decided by the shared checks
    /// and the test run, not here.
    /// </summary>
    private static string? CheckSweep(ImplementationScenarioCheckContext ctx)
    {
        var compilation = ctx.Compile(CoreFolder.TrimEnd('/'));
        var remaining = new List<string>();
        foreach (var path in TargetPaths)
        {
            if (!ctx.Exists(path))
            {
                return $"missing: {path}";
            }

            var model = compilation.ModelFor(path);
            foreach (var creation in model.SyntaxTree.GetRoot().DescendantNodes().OfType<BaseObjectCreationExpressionSyntax>())
            {
                if (!IsPlainDictionary(compilation.TypeOf(creation))
                    || model.GetOperation(creation)?.Parent is IArgumentOperation { Parameter.Name: "FailedFiles" })
                {
                    continue;
                }

                remaining.Add(DescribeSite(creation));
            }
        }

        if (remaining.Count == 0)
        {
            return null;
        }

        var named = new List<string>();
        var firstLine = ctx.FinalMessage?.Split('\n').FirstOrDefault(line => !string.IsNullOrWhiteSpace(line));
        if (firstLine is not null)
        {
            named.Add(firstLine);
        }

        foreach (var (label, value) in ScenarioReport.Parse(ctx.FinalMessage))
        {
            named.Add(label);
            named.Add(value);
        }

        var unnamed = remaining.Distinct().Where(method => !named.Any(text => NamesMethod(text, method))).ToList();
        return unnamed.Count == 0
            ? null
            : $"unconverted site(s) not named in the Report (the method name, one line each, or `none`): {string.Join(", ", unnamed)}";
    }

    private static bool IsPlainDictionary(ITypeSymbol? type) =>
        type is INamedTypeSymbol { Name: "Dictionary", TypeArguments: [{ Name: "FilePath" }, { SpecialType: SpecialType.System_String }] };

    /// <summary>True when <paramref name="text"/> contains <paramref name="method"/> as a whole identifier (case-sensitive).</summary>
    private static bool NamesMethod(string text, string method)
    {
        for (var index = text.IndexOf(method, StringComparison.Ordinal); index >= 0; index = text.IndexOf(method, index + 1, StringComparison.Ordinal))
        {
            var before = index == 0 ? ' ' : text[index - 1];
            var afterIndex = index + method.Length;
            var after = afterIndex >= text.Length ? ' ' : text[afterIndex];
            if (!char.IsLetterOrDigit(before) && before != '_' && !char.IsLetterOrDigit(after) && after != '_')
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>The name of the method enclosing a creation site, "?" when there is none.</summary>
    private static string DescribeSite(SyntaxNode creation) =>
        creation.Ancestors().OfType<MethodDeclarationSyntax>().FirstOrDefault()?.Identifier.ValueText ?? "?";
}
